var countBattleships = function(board) {
    let count = 0;
    const m = board.length, n = board[0].length;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (board[i][j] === 'X') {
                if (i > 0 && board[i - 1][j] === 'X') continue;
                if (j > 0 && board[i][j - 1] === 'X') continue;
                count++;
            }
        }
    }
    return count;
};
